<template>
  <div :class="['calculator', darkMode ? 'dark' : 'light']">
    <div class="theme-toggle">
      <label>
        <input type="checkbox" v-model="darkMode" />
        Dark Mode
      </label>
    </div>
    <div class="typed-header" ref="typedHeader"></div>
    <div class="display" ref="display">{{ current }}</div>
    <div class="buttons">
      <button
        v-for="btn in buttons"
        :key="btn"
        @click="press($event, btn)"
        :class="getButtonClass(btn)"
      >
        {{ btn }}
      </button>
    </div>
  </div>
</template>

<script>
import gsap from 'gsap';
import Typed from 'typed.js';
import { Howl } from 'howler';
import mexp from 'math-expression-evaluator';

export default {
  data() {
    return {
      current: '',
      darkMode: true,
      buttons: ['1','2','3','4','5','6','7','8','9','0','+','-','/','.','=','C'],
      sound: null,
      typed: null,
      typedMessages: [
        "it's a calculator",
        "it logs things to GTM",
        "how's the inp doing?",
        "ERR_CERT_COMMON_NAME_INVALID... just kidding",
        "x-xss-protection has added",
        "now there's 9999 ERRORS IN THE ISSUES OH GOD—",
        "HeY YoUr CSP iS BlOcKinG SoMe ReSoUrCeS",
        "vEriFy CSS"
      ]
    };
  },
  mounted() {
    this.startTyped();

    gsap.from('.calculator', {
      duration: 1,
      scale: 0.8,
      opacity: 0,
      ease: 'bounce'
    });

    this.sound = new Howl({
      src: ['click.mp3'],
      volume: 0.5
    });

    fetch('https://mythic-calculator.ngrok-free.app', {
      headers: {
        'ngrok-skip-browser-warning': 'true'
      }
    }).catch(() => {});
  },
  methods: {
    startTyped() {
      const cycleTyped = () => {
        const message = this.typedMessages[Math.floor(Math.random() * this.typedMessages.length)];
        if (this.typed) this.typed.destroy();
        this.typed = new Typed(this.$refs.typedHeader, {
          strings: [message],
          typeSpeed: 40,
          backSpeed: 20,
          backDelay: 2000,
          showCursor: false,
          onComplete: () => setTimeout(cycleTyped, 3000)
        });
      };
      cycleTyped();
    },
    getButtonClass(btn) {
      if (btn === '=') return 'btn-equals';
      if (btn === 'C') return 'btn-clear';
      return 'btn-default';
    },
    press(event, btn) {
      this.sound.play();

      const el = event.target;
      gsap.fromTo(el,
        { scale: 1, borderRadius: '5px' },
        { scale: 1.2, borderRadius: '50%', duration: 0.2, yoyo: true, repeat: 1 }
      );

      if (['+', '-', '='].includes(btn)) {
        gtag('event', 'button_press', {
          event_category: 'Calculator',
          event_label: btn,
          value: btn
        });
      }

      if (btn === 'C') {
        this.current = '';
        return;
      }

      if (btn === '=') {
        try {
          if (!this.current || /[+\-\/.]$/.test(this.current)) {
            throw new Error('Invalid expression');
          }
          this.current = mexp.eval(this.current).toString();
          gsap.fromTo(this.$refs.display, { scale: 1 }, {
            scale: 1.2,
            duration: 0.2,
            yoyo: true,
            repeat: 1
          });
        } catch {
          this.current = 'Error';
        }
      } else {
        const lastChar = this.current.slice(-1);
        if ((/[+\-\/.]/.test(lastChar) && /[+\-\/.]/.test(btn)) || (btn === '.' && this.current.includes('.'))) {
          return; // skip invalid input
        }
        this.current += btn;
      }
    }
  }
};
</script>

